<script setup lang="ts">
import type { Project } from '~~/shared/types/projects'
import type { ProcessDocument,ProcessPhase } from '~~/shared/types/project-process'
import type { EstimateField } from '~~/shared/types/estimate'
import { executionMoney } from '~~/shared/utils/project-execution'
const props=defineProps<{project:Project}>(),auth=useAuthStore(),supabase=useNuxtApp().$supabase
const query=useProjectProcessData(()=>props.project.id)
const search=ref(''),type=ref('all'),onlyOpen=ref(false),expanded=ref(false),page=ref(1),selectedId=ref(''),selectedPhase=ref<ProcessPhase>('contracts'),detailTab=ref('documents'),error=ref(''),exporting=ref(''),pageSize=6
const contracts=computed(()=>query.data.value?.contracts??[])
const filtered=computed(()=>contracts.value.filter(c=>{
 const text=`${c.number} ${c.sellerName} ${c.buyerName} ${c.seller?.inn??''} ${c.buyer?.inn??''} ${c.documents.map(d=>d.title+' '+d.number).join(' ')} ${c.scope.map(i=>i.name).join(' ')}`.toLocaleLowerCase('ru')
 return (type.value==='all'||c.source===type.value)&&(!onlyOpen.value||c.status!=='complete')&&search.value.toLocaleLowerCase('ru').trim().split(/\s+/).filter(Boolean).every(token=>text.includes(token))
}))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize)),selected=computed(()=>filtered.value.find(c=>c.id===selectedId.value))
watch([search,type,onlyOpen],()=>{page.value=1})
watch(()=>filtered.value.length,count=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(count/pageSize)))})
watch(visible,rows=>{if(!rows.some(c=>c.id===selectedId.value))selectedId.value=rows[0]?.id??''},{immediate:true})
const icons:Record<ProcessPhase,string>={parties:'i-lucide-users-round',estimate:'i-lucide-calculator',contracts:'i-lucide-file-signature',execution:'i-lucide-truck',closing:'i-lucide-clipboard-check'}
function select(id:string,phase:ProcessPhase){selectedId.value=id;selectedPhase.value=phase;detailTab.value=phase==='parties'?'parties':phase==='estimate'?'items':phase==='execution'?'steps':'documents';error.value=''}
const money=(value:number|null|undefined)=>value===null||value===undefined?'—':executionMoney(value)
const date=(value:string|undefined)=>value?value.split('-').reverse().join('.'):'—'
const status=(value:string)=>value==='complete'?'Подтверждено':value==='overdue'?'Просрочено':'Ожидает подтверждения'
const person=(id:string)=>{const member=props.project.members.find(m=>m.userId===id);return member?.fullName||member?.email||'Участник проекта'}
const auditTime=(value:string)=>value?new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Moscow'}).format(new Date(value)):''
const fieldValue=(field:EstimateField)=>field.type==='money'&&field.value?money(Number(field.value)):field.type==='date'?date(field.value):field.value||'—'
const selectedStageLink=computed(()=>`/projects/${props.project.id}/${selectedPhase.value==='parties'?'contracts':selectedPhase.value==='estimate'?'estimate':selectedPhase.value==='contracts'?'contracts':selectedPhase.value==='execution'?'execution':'closing'}`)
async function download(document:ProcessDocument,format:'docx'|'pdf'){
 if(!selected.value||exporting.value)return;exporting.value=document.id+format;error.value='';const user=auth.user?.id,contractId=selected.value.id
 try{const{data}=await supabase.auth.getSession();if(!data.session||data.session.user.id!==user)throw Error('Войдите в аккаунт');const blob=await $fetch<Blob>(`/api/projects/${props.project.id}/${document.stage}/export`,{method:'POST',retry:0,responseType:'blob',headers:{Authorization:`Bearer ${data.session.access_token}`},body:{contractId,kind:document.kind,format,...(document.appendixId?{appendixId:document.appendixId}:{})}});if(auth.user?.id!==user)return;const url=URL.createObjectURL(blob),a=window.document.createElement('a');a.href=url;a.download=`${document.title.replace(/[\\/:*?"<>|]/g,'-')}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e:any){if(e?.data instanceof Blob){try{error.value=JSON.parse(await e.data.text()).message}catch{error.value='Не удалось скачать документ'}}else error.value=e?.data?.message||e.message}finally{exporting.value=''}
}
</script>
<template>
 <section class="project-process" aria-label="Взаимосвязь проекта">
  <header class="process-heading"><div><span class="process-eyebrow">ПРОЕКТ В ДВИЖЕНИИ</span><h2>Карта проекта</h2><p>Участники, суммы и документы — от начала проекта до закрытия каждого договора.</p></div><UButton label="Обновить карту" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="query.isFetching.value" @click="query.refetch()"/></header>
  <p v-if="query.isPending.value" class="process-muted">Собираем связи проекта…</p><UAlert v-else-if="query.error.value" color="error" title="Не удалось загрузить взаимосвязи проекта" :actions="[{label:'Повторить',onClick:()=>query.refetch()}]"/>
  <template v-else-if="query.data.value">
   <details v-if="query.data.value.unallocatedItems.length" class="process-unassigned"><summary>Позиции без связи с договором поставщика: {{query.data.value.unallocatedItems.length}}</summary><ul><li v-for="item in query.data.value.unallocatedItems" :key="item.id"><span>{{item.name}} · {{item.counterparty||'Поставщик не выбран'}}</span><b>{{money(item.total)}}</b></li></ul><NuxtLink :to="`/projects/${project.id}/estimate`">Открыть смету →</NuxtLink></details>
   <div v-if="!contracts.length" class="process-empty"><UIcon name="i-lucide-git-branch"/><h3>Связи появятся после добавления договоров</h3><p>Смета определит суммы, а договоры — стороны и последовательность документов.</p><UButton :to="`/projects/${project.id}/contracts`" label="Открыть договоры" color="neutral" variant="outline"/></div>
   <template v-else>
    <div class="process-toolbar"><UInput v-model="search" icon="i-lucide-search" placeholder="Компания, договор, документ или позиция" aria-label="Поиск по карте проекта" class="process-search"/><USelect v-model="type" :items="[{label:'Все договоры',value:'all'},{label:'Заказчик',value:'revenue'},{label:'Поставщики',value:'expenses'}]" aria-label="Ветки карты проекта"/><UCheckbox v-model="onlyOpen" label="Только незакрытые"/><UButton :label="expanded?'Свернуть карту':'Развернуть карту'" :icon="expanded?'i-lucide-minimize-2':'i-lucide-maximize-2'" color="neutral" variant="ghost" @click="expanded=!expanded"/></div>
    <div v-if="!filtered.length" class="process-empty process-empty-small">По заданным условиям ветки не найдены.</div>
    <div v-else class="process-canvas" :class="{expanded}" tabindex="0" aria-label="Карта процесса, каждая строка — отдельный договор"><div class="process-canvas-content"><div class="process-columns" aria-hidden="true"><span>Кто участвует</span><span>Откуда сумма</span><span>Что согласовано</span><span>Что нужно выполнить</span><span>Чем закрывается</span></div><div v-for="contract in visible" :key="contract.id" class="process-row" :class="{'process-customer-row':contract.source==='revenue'}"><button v-for="step in contract.steps" :key="step.id" class="process-node" :class="[`timeline-${step.status}`,{'is-selected':selectedId===contract.id&&selectedPhase===step.phase}]" :aria-pressed="selectedId===contract.id&&selectedPhase===step.phase" :aria-label="`${step.label}: договор ${contract.number}`" @click="select(contract.id,step.phase)"><span class="process-node-label"><UIcon :name="icons[step.phase]"/>{{step.label}}</span><strong>{{step.summary}}</strong><span v-if="step.phase==='parties'" class="process-parties-flow"><b>{{contract.sellerName}}</b><UIcon name="i-lucide-arrow-down"/><b>{{contract.buyerName}}</b></span><span v-else>{{step.detail}}</span><small v-if="step.phase==='parties'">Исполнитель → заказчик</small><small v-else-if="step.phase==='estimate'">{{contract.source==='revenue'?'Сумма продажи':'Затраты на закупку'}}</small><small v-else class="timeline-status">{{status(step.status)}}</small></button></div></div></div>
    <div v-if="filtered.length>pageSize" class="process-pagination"><UButton label="Предыдущие договоры" color="neutral" variant="outline" :disabled="page===1" @click="page--"/><span>{{page}} / {{Math.ceil(filtered.length/pageSize)}}</span><UButton label="Следующие договоры" color="neutral" variant="outline" :disabled="page*pageSize>=filtered.length" @click="page++"/></div>
    <section v-if="selected" class="process-inspector" aria-label="Подробности выбранной связи"><header class="process-inspector-heading"><div><small>{{selected.source==='revenue'?'Заказчик':'Поставщик'}}</small><h3>Договор № {{selected.number}}</h3><p>{{selected.sellerName}} → {{selected.buyerName}}</p></div><div class="process-inspector-total"><strong>{{money(selected.amount)}}</strong><small>В том числе НДС {{money(selected.vat)}}</small><NuxtLink :to="selectedStageLink">Открыть этап →</NuxtLink></div></header>
     <UAlert v-if="selected.issue||selected.needsReview" color="warning" :description="selected.issue||'Данные изменились. Нужны повторные подтверждения.'" class="mb-4"/><UAlert v-if="error" color="error" :description="error" class="mb-4"/>
     <nav class="process-detail-tabs" aria-label="Детали ветки проекта"><button :aria-pressed="detailTab==='documents'" @click="detailTab='documents'">Документы · {{selected.documents.length}}</button><button :aria-pressed="detailTab==='steps'" @click="detailTab='steps'">Кто и что делает</button><button :aria-pressed="detailTab==='items'" @click="detailTab='items'">Позиции сметы · {{selected.scope.length}}</button><button :aria-pressed="detailTab==='parties'" @click="detailTab='parties'">Стороны и расчёты</button></nav>
     <div v-if="detailTab==='documents'" class="process-document-list"><article v-for="doc in selected.documents" :key="doc.id" class="process-document"><span class="process-document-icon"><UIcon :name="doc.kind==='invoice'?'i-lucide-receipt':doc.kind==='act'||doc.kind==='upd'?'i-lucide-file-check-2':'i-lucide-file-text'"/></span><div><h4>{{doc.title}}</h4><p>{{doc.date?date(doc.date):'Дата не заполнена'}} · {{doc.automatic?'Автоматический черновик':'Документ проекта'}}</p><small class="process-document-status" :class="`is-${doc.status}`">{{doc.confirmed?doc.kind==='invoice'?'Предоплата подтверждена':'Подписание подтверждено':doc.status==='overdue'?'Подтверждение просрочено':'Ожидает подтверждения'}}</small><small v-if="doc.confirmedAt" class="process-audit">В системе: {{person(doc.confirmedBy)}} · {{auditTime(doc.confirmedAt)}}</small><small v-if="doc.issue" class="process-doc-issue">{{doc.issue}}</small></div><div class="process-document-actions"><UButton label="Word" color="neutral" variant="outline" size="sm" :disabled="!!exporting||!!doc.issue" :loading="exporting===doc.id+'docx'" @click="download(doc,'docx')"/><UButton label="PDF" color="neutral" variant="outline" size="sm" :disabled="!!exporting||!!doc.issue" :loading="exporting===doc.id+'pdf'" @click="download(doc,'pdf')"/></div></article></div>
     <ol v-else-if="detailTab==='steps'" class="process-action-list"><li v-for="(check,index) in selected.checks" :key="check.key"><span class="process-action-marker" :class="`is-${check.status}`"><UIcon v-if="check.confirmed" name="i-lucide-check"/><template v-else>{{index+1}}</template></span><div><h4>{{check.label}}</h4><p>{{check.action}}</p><small>Срок: {{check.deadline?date(check.deadline):'Не задан'}} · {{status(check.status)}}</small><small v-if="check.confirmed&&check.at" class="process-audit">Отметил в системе: {{person(check.by)}} · {{auditTime(check.at)}}</small></div></li><li class="process-final"><UIcon name="i-lucide-flag"/><div><h4>{{selected.status==='complete'?'Договор закрыт':'Закрытие после всех подтверждений'}}</h4><p>{{selected.done}} из {{selected.total}} обязательных пунктов подтверждено</p></div></li></ol>
     <div v-else-if="detailTab==='items'" class="process-item-details"><p class="process-muted">{{selected.scopeBasis}}</p><div class="process-table-scroll"><table><thead><tr><th>Позиция</th><th>Исполнитель</th><th>Количество</th><th>Затраты, ₽</th><th>Срок</th></tr></thead><tbody><tr v-for="item in selected.scope" :key="item.id"><td><strong>{{item.name}}</strong><a v-if="item.link" :href="item.link" target="_blank" rel="noopener noreferrer">Ссылка ↗</a><details v-if="item.fields.length"><summary>Дополнительные поля · {{item.fields.length}}</summary><dl><template v-for="field in item.fields" :key="field.id"><dt>{{field.label}}</dt><dd><a v-if="field.type==='link'&&field.value" :href="field.value" target="_blank" rel="noopener noreferrer">{{field.value}}</a><template v-else>{{fieldValue(field)}}</template></dd></template></dl></details></td><td>{{item.internalCost?'Внутренние работы':item.counterparty||'Не назначен'}}</td><td>{{item.quantity}} {{item.unit}}</td><td>{{money(item.total)}}<small>Цена: {{money(item.price)}} · НДС: {{money(item.vat)}}</small></td><td>{{date(item.deadline)}}</td></tr></tbody></table></div><p v-if="!selected.scope.length" class="process-muted mt-4">В смете нет связанных позиций.</p><dl v-if="query.data.value.estimate.fields.length" class="process-extra-fields"><template v-for="field in query.data.value.estimate.fields" :key="field.id"><dt>{{field.label}}</dt><dd>{{fieldValue(field)}}</dd></template></dl></div>
     <div v-else class="process-parties-details"><div class="process-money-flow"><span>{{selected.buyerName}}</span><UIcon name="i-lucide-arrow-right"/><strong>{{money(selected.amount)}}</strong><UIcon name="i-lucide-arrow-right"/><span>{{selected.sellerName}}</span><small>Направление оплаты по договору · перечисление денег подтверждается отдельно</small></div><div class="process-party-grid"><article v-for="(party,index) in [selected.seller,selected.buyer]" :key="party?.id??index"><small>{{index===0?'Продавец / исполнитель':'Покупатель / заказчик'}}</small><h4>{{party?.company??(index===0?selected.sellerName:selected.buyerName)}}</h4><span v-if="party?.isOwnLegalEntity" class="process-own-entity">Наше юр. лицо</span><dl v-if="party"><dt>ИНН / КПП</dt><dd>{{party.inn||'—'}} / {{party.kpp||'—'}}</dd><dt>Руководитель</dt><dd>{{party.director||'—'}}</dd><dt>Адрес</dt><dd>{{party.address||'—'}}</dd><dt>Расчётный счёт</dt><dd>{{party.bankAccount||'—'}}</dd></dl></article></div><p v-if="selected.prepayment.enabled" class="process-muted mt-4">Предоплата {{selected.prepayment.percent}}%: {{money(selected.prepayment.amount)}}. В том числе НДС {{money(selected.prepayment.vat)}}.</p><p v-else class="process-muted mt-4">Предоплата не предусмотрена.</p></div>
    </section>
   </template>
  </template>
 </section>
</template>
<style scoped>
.project-process{margin:38px 0;padding:28px;border:1px solid #dfe6ef;border-radius:24px;background:linear-gradient(155deg,#f8faff,#fff 50%,#f9fafc);color:#475569}.process-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin-bottom:26px}.process-eyebrow{font-size:10px;letter-spacing:1.6px;color:#94a3b8;font-weight:600}.process-heading h2{font-size:26px;font-weight:650;color:#334155;margin:8px 0}.process-heading p{font-size:13px;line-height:1.7;color:#8292a8;max-width:650px}.process-toolbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin:26px 0 18px}.process-search{flex:1;min-width:250px}.process-canvas{overflow:auto;max-height:480px;border:1px solid #dfe6ef;border-radius:18px;background-color:#f8faff;background-image:radial-gradient(#dce3ed .8px,transparent .8px);background-size:18px 18px;padding:20px;scrollbar-color:#c3ccd9 transparent}.process-canvas.expanded{max-height:850px}.process-canvas-content{min-width:1060px}.process-columns,.process-row{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:28px}.process-columns{font-size:10px;letter-spacing:.4px;color:#94a3b8;margin:0 0 12px;padding:0 8px}.process-row{padding-bottom:20px}.process-row+.process-row{padding-top:4px}.process-customer-row{border-bottom:1px solid #cbd5e1;margin-bottom:24px;padding-bottom:24px}.process-node{position:relative;text-align:left;background:#fff;border:1px solid #dbe3ee;border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:12px;min-width:0;min-height:170px;transition:box-shadow .16s,transform .16s}.process-node:not(:last-child)::after{content:'→';position:absolute;top:calc(50% - 11px);left:100%;width:28px;font-size:22px;line-height:22px;color:#a4b0c1;text-align:center;pointer-events:none}.process-node:hover{transform:translateY(-2px);box-shadow:0 5px 14px #0f172a08}.process-node.is-selected{box-shadow:0 0 0 2px var(--ui-primary)}.process-node:focus-visible{outline:2px solid var(--ui-primary);outline-offset:4p